mxEditor.add:
function (div)
{
	console.log('createTasks...');

	// View filter panel — always visible, not a .task.
	// One checkbox per distinct Transition method name. Unchecking hides
	// edges of that type so overlapping flows are easier to read.
	var view = document.createElement('div');
	view.id = 'ViewFilter';
	view.className = 'view-panel';
	view.innerHTML =
		'<div class="view-header">' +
			'<b>View</b> ' +
			'<a href="#" id="view-show-all">all</a> | ' +
			'<a href="#" id="view-hide-all">none</a>' +
		'</div>' +
		'<div id="view-methods"></div>' +
		'<div class="view-header" id="view-plans-header" style="display:none; margin-top:6px;">' +
			'<b>Plans</b>' +
		'</div>' +
		'<div id="view-plans"></div>';
	div.appendChild(view);

	if (window.flowTasks && window.flowTasks.initView) {
		window.flowTasks.initView(this.graph);
	}

	var sep = document.createElement('hr');
	sep.className = 'view-sep';
	div.appendChild(sep);

	// State properties panel
	var state = document.createElement('div');
	state.id = 'State';
	state.className = 'task';
	state.style.display = 'none';
	div.appendChild(state);
	$('#State').load('./state.html #state-view', function() {
		if (window.flowUtils) window.flowUtils.foldHintsIntoTips(this);
	});

	// Gateway properties panel (same template as State). #Ingress and
	// #Egress remain for legacy saved-XML diagrams.
	var gateway = document.createElement('div');
	gateway.id = 'Gateway';
	gateway.className = 'task';
	gateway.style.display = 'none';
	div.appendChild(gateway);
	$('#Gateway').load('./state.html #state-view', function() {
		if (window.flowUtils) window.flowUtils.foldHintsIntoTips(this);
	});

	var ingress = document.createElement('div');
	ingress.id = 'Ingress';
	ingress.className = 'task';
	ingress.style.display = 'none';
	div.appendChild(ingress);
	$('#Ingress').load('./state.html #state-view', function() {
		if (window.flowUtils) window.flowUtils.foldHintsIntoTips(this);
	});

	var egress = document.createElement('div');
	egress.id = 'Egress';
	egress.className = 'task';
	egress.style.display = 'none';
	div.appendChild(egress);
	$('#Egress').load('./state.html #state-view', function() {
		if (window.flowUtils) window.flowUtils.foldHintsIntoTips(this);
	});

	// Transition properties panel
	var transition = document.createElement('div');
	transition.id = 'Transition';
	transition.className = 'task';
	transition.style.display = 'none';
	div.appendChild(transition);
	$('#Transition').load('./transition.html #transition-view', function() {
		if (window.flowUtils) window.flowUtils.foldHintsIntoTips(this);
	});

	// Global config panel (FlowModel root)
	var config = document.createElement('div');
	config.id = 'FlowModel';
	config.className = 'task';
	config.style.display = 'none';
	div.appendChild(config);
	$('#FlowModel').load('./config.html #config-view', function() {
		if (window.flowUtils) window.flowUtils.foldHintsIntoTips(this);
	});
}

function (div)
{
	// The panels differ in height — State carries selectors and plans,
	// Transition a couple of fields — and mxWindow keeps whatever height
	// it was built with, so the taller panel used to lose its last row
	// off the bottom edge. Size the window to the panel each time, and
	// only scroll when the panel is taller than the screen allows.
	if (this.tasks == null || this.tasks.div == null || div == null) {
		return;
	}
	var wnd = this.tasks;
	var titleHeight = (wnd.title != null) ? wnd.title.offsetHeight : 22;
	// The +14 is breathing room: sized to the exact content height, the
	// last control sits flush against the window's bottom edge and
	// reads as cut off even when all of it is there.
	var chrome = titleHeight + wnd.contentHeightCorrection + 14;
	var natural = div.scrollHeight + chrome;
	var room = window.innerHeight - wnd.div.offsetTop - 24;
	var height = Math.min(natural, Math.max(160, room));
	wnd.setSize(wnd.div.offsetWidth, height);
	wnd.setScrollable(height < natural);
}

function (div)
{
	console.log('refreshTasks...');
	if (this.tasks != null)
	{
		var title = 'FlowModel';

		// The panels are about to be swapped/rebuilt; a pinned
		// field-help popup would outlive its ⓘ icon.
		if (window.flowUtils) {
			window.flowUtils.hideInfoTip();
		}

		$('.task').css('display','none');

		var selectedCell = this.graph.getSelectionCell();
		window.flowGraph = this.graph;

		if (selectedCell != null && selectedCell.value != null) {
			title = selectedCell.value.tagName;
			window.flowSelectedCell = selectedCell;
		} else {
			// Nothing selected — show the global FlowModel config
			var rootCell = this.graph.getModel().getCell('0');
			window.flowSelectedCell = rootCell;
			title = 'FlowModel';
		}

		this.tasks.setTitle(title);
		$('#'+title).css('display','block');

		// Selector fieldsets are rebuilt per selection, so their hints
		// arrive after the panel's own load callback ran.
		if (window.flowUtils) {
			window.flowUtils.foldHintsIntoTips(document.getElementById(title));
		}

		if (typeof window.flowTasks !== 'undefined' && window.flowTasks.loadFromCell) {
			window.flowTasks.loadFromCell(window.flowSelectedCell);
		}

		this.fitTasksWindow(div);
	}
}

function (div)
{
	console.log('showTasks...');

	if (this.tasks == null) {
		var div = document.createElement('div');
		div.style.padding = '6px';

		// 260, not 300: the root panel is two fields and a line of
		// prose now, and the State and Transition panels that share
		// this window are input rows rather than reading. Every pixel
		// here is taken off the canvas, which is the subject.
		var w = document.body.clientWidth;
		var wnd = new mxWindow(mxResources.get(this.tasksResource)
				|| this.tasksResource, div, w - 280, this.tasksTop, 260);
		wnd.setClosable(true);
		wnd.destroyOnClose = false;

		var funct = mxUtils.bind(this, function(sender) {
			this.refreshTasks(div);
		});

		this.graph.getModel().addListener(mxEvent.CHANGE, funct);
		this.graph.getSelectionModel().addListener(mxEvent.CHANGE, funct);
		this.graph.addListener(mxEvent.ROOT, funct);

		if (this.tasksWindowImage != null) {
			wnd.setImage(this.tasksWindowImage);
		}

		this.tasks = wnd;

		this.createTasks(div);
	}

	this.tasks.setVisible(true);
	this.fitTasksWindow(this.tasks.content);
}
